  spi_miso_in,
  spi_miso_oe,
  spi_miso_out,
  spi_mosi_in,
  spi_mosi_oe,
  spi_mosi_out
)
;
input pclk;
input presetn;
input [31:0] paddr;
input penable;
output [31:0] prdata;
output pready;
input psel;
input [31:0] pwdata;
input pwrite;
input spi_default_as_slave;
input spi_cs_n_in;
input spi_hold_n_in;
output spi_hold_n_oe;
output spi_hold_n_out;
input spi_wp_n_in;
output spi_wp_n_oe;
output spi_wp_n_out;
input spi_clock;
input spi_rstn;
output spi_boot_intr;
