output spi_clk_out;
output spi_cs_n_oe;
output spi_cs_n_out;
input spi_miso_in;
output spi_miso_oe;
output spi_miso_out;
input spi_mosi_in;
output spi_mosi_oe;
output spi_mosi_out;
wire spi_clock_d_1;
wire VCC;
wire GND;
  INV spi_clock_d_s (
    .O(spi_clock_d_1),
    .I(spi_clock) 
);
  \~apb_spi.APB_SPI_Top  u_apb_spi (
    .pclk(pclk),
